Here is my Kora 2.0 auth interceptor. It compiles and the app starts, but every request reaches the controller without any credentials being checked.

@Tag(HttpServerModule.class)
@Component
public final class AuthInterceptor implements HttpServerInterceptor {
    @Override
    public HttpServerResponse intercept(HttpServerRequest request, InterceptChain chain) throws Exception {
        if (request.headers().getFirst("x-api-key") == null) {
            throw HttpServerResponseException.of(401, "Unauthorized");
        }
        return chain.process(request);
    }
}

